use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let t1 = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || {
            let _a = a.lock().unwrap();
            let _b = b.lock().unwrap();
            // critical work holding both locks
        })
    };

    let t2 = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || {
            let _a = a.lock().unwrap();
            let _b = b.lock().unwrap();
            // critical work holding both locks
        })
    };

    t1.join().unwrap();
    t2.join().unwrap();

    println!("DONE t1=1 t2=1");
}
```

Both workers acquire locks `a` and `b` in the same order (a then b), so no circular wait is possible (R5/R8). Locks are acquired with blocking `lock()` calls (R4), held simultaneously during the critical work (R3), and released via RAII guard drops before the worker finishes (R7). The main thread joins both workers before printing and exiting (R6, R9).

```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn worker(
    name: &'static str,
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    count: Arc<Mutex<u32>>,
) {
    // R4: blocking lock acquisition (waits until free, then continues).
    // R5: always acquire in the same order (a then b), so no circular wait
    //     is possible and deadlock can never occur (R8).
    {
        let _a = a.lock().unwrap(); // hold a
        let _b = b.lock().unwrap(); // acquire b while holding a

        // R3: both locks are held simultaneously here — critical work.
        let mut c = count.lock().unwrap();
        match name {
            "t1" => *c |= 1,
            "t2" => *c |= 2,
            _ => {}
        }
    }
    // R7: both locks released here (guards dropped at end of block).

    let _ = name;
}

fn main() {
    // R2: two shared locks; each can be held by only one worker at a time
    // because Mutex guarantees exclusive access.
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let count = Arc::new(Mutex::new(0u32));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let c1 = Arc::clone(&count);
    let h1 = thread::spawn(move || worker("t1", a1, b1, c1)); // R1: worker t1

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let c2 = Arc::clone(&count);
    let h2 = thread::spawn(move || worker("t2", a2, b2, c2)); // R1: worker t2

    // R6: main waits for both workers to finish.
    h1.join().unwrap();
    h2.join().unwrap();

    let c = *count.lock().unwrap();
    // R9: exactly the required line, then exit.
    if c == 3 {
        println!("DONE t1=1 t2=1");
    } else {
        println!("DONE t1={} t2={}", (c & 1), ((c >> 1) & 1));
    }
}
```

Key safety points:

- **R5/R8 (no deadlock):** Both workers acquire locks in a fixed global order (`a` before `b`). With a consistent ordering, a circular wait cannot form, so every interleaving terminates.
- **R3:** Each worker holds both guard objects simultaneously inside the same scope while doing the critical work.
- **R4:** `Mutex::lock()` blocks until the lock is free, then continues.
- **R7:** RAII guards (`MutexGuard`) automatically release both locks when the scope ends — even on early return or panic (after unwrapping).

