// Entities: role `helper` (auxiliary routine), main task drives the loop.

use std::thread;

/// The auxiliary routine. It takes no arguments and returns nothing;
/// it shares no mutexes, counters, or other state with the main task,
/// so no two tasks ever contend for a resource (R2).
fn helper() {
    // Completes entirely on its own before returning control (R3).
}

/// One "call sequence": invoke the auxiliary routine once.
fn call_sequence() {
    let handle = thread::Builder::new()
        .name("helper-role".to_string())
        .spawn(helper)
        .expect("spawn helper");
    // Joining guarantees the auxiliary call runs to completion
    // before the calling task starts the next call (R3).
    handle.join().expect("helper panicked");
}

fn main() {
    // Main task: call the auxiliary routine, then begin the same
    // call sequence again (R1). A bounded local repetition count
    // ensures every interleaving terminates (R4) while still
    // exercising the repeat.
    let repetitions = 2;
    for _ in 0..repetitions {
        call_sequence();
    }

    // Exactly one line of output, then exit (R5).
    println!("DONE done=1");
}
```

Notes on the requirements:

- **R1**: `main` executes `call_sequence()` (which calls `helper`), then begins the same call sequence again via the loop.
- **R2**: `helper` and the main task touch no shared data; the only synchronization is the join, which is not contention but sequencing.
- **R3**: `join()` forces each auxiliary call to run to completion before the next starts.
- **R4**: The repetition count is fixed and local, so every schedule terminates.
- **R5**: The program prints exactly `DONE done=1` and exits.

```rust
use std::sync::{Arc, Condvar, Mutex};

struct Semaphore {
    count: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(n: usize) -> Self {
        Semaphore { count: Mutex::new(n), cv: Condvar::new() }
    }

    fn acquire(&self) {
        let mut count = self.count.lock().unwrap();
        while *count == 0 {
            count = self.cv.wait(count).unwrap();
        }
        *count -= 1;
    }

    fn release(&self) {
        let mut count = self.count.lock().unwrap();
        *count += 1;
        self.cv.notify_one();
    }
}

fn worker(name: &'static str, s: Arc<Semaphore>) {
    let rounds: usize = 3;
    for _ in 0..rounds {
        s.acquire(); // hold permit while working (R3)
        // simulate work while holding the permit
        for _ in 0..5 {
            std::hint::spin_loop();
        }
        s.release(); // released on every path, exactly once per acquire (R4)
    }
    let _ = name;
}

fn main() {
    let s = Arc::new(Semaphore::new(1)); // one permit (R2)

    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let h1 = std::thread::spawn(move || worker("w1", s1));
    let h2 = std::thread::spawn(move || worker("w2", s2));

    h1.join().unwrap();
    h2.join().unwrap();

    // R7: exactly `DONE done=1`
    let remaining = *s.count.lock().unwrap();
    println!("DONE done={}", remaining);
}
```

Notes on the requirements:
- R1: `main` starts the two worker threads and joins both via a supervising main scope.
- R2: `s` is a single shared counting permit pool initialized to exactly one permit.
- R3: each worker only performs its work while holding the permit acquired from `s`.
- R4: each worker acquires/releases the permit 3 times; each `acquire` is followed by exactly one `release` (including on the loop's normal exit path).
- R5: `acquire` uses a `Condvar` wait, so a waiting worker blocks without holding the mutex, letting the permit-holder release the permit so the waiter can proceed.
- R6: fair Mutex/Condvar handoff guarantees both workers drain their 3 rounds and terminate regardless of interleaving; no permit is lost, so `w1` and `w2` always finish.
- R7: the program prints exactly `DONE done=1` (the pool's final permit count) and exits.

